export default function WorkOrderDetailsDialog({
  isOpen,
  onClose,
  workOrder,
  onEdit,
  onMove,
  onSplit,
  onComplete,
  onRestore,
  onUpdate,
  onDelete
}) {
  const { currentUser, sessionToken } = useAuth();
  const [allWorkOrders, setAllWorkOrders] = useState([]);
  const [relatedDataReadError, setRelatedDataReadError] = useState("");
  const [relatedDataVerified, setRelatedDataVerified] = useState(false);
  const [riders, setRiders] = useState([]);
  const [parentWorkOrder, setParentWorkOrder] = useState(null);
  const [dependencies, setDependencies] = useState([]);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [deletingWorkOrder, setDeletingWorkOrder] = useState(false);
  const [showCompleteConfirm, setShowCompleteConfirm] = useState(false);
  const [showCompletedNotes, setShowCompletedNotes] = useState(false);
  const [isEditingDependency, setIsEditingDependency] = useState(false);
  const [allUsers, setAllUsers] = useState([]);

  // Edit states
  const [editingField, setEditingField] = useState(null);
  const [editValues, setEditValues] = useState({});
  const inlineEditBaselineRef = useRef({});
  const inlineEditSavingRef = useRef(new Set());
  const [inlineEditError, setInlineEditError] = useState("");
  const [uploading, setUploading] = useState(false);
  const [newDependency, setNewDependency] = useState({
    trigger_type: "stage_change",
    trigger_value: "",
    action_type: "move_stage",
    action_value: "",
    target_work_order_id: ""
  });
  const [isAddingTask, setIsAddingTask] = useState(false);
  const [newTaskText, setNewTaskText] = useState("");
  const [newTaskAssignedTo, setNewTaskAssignedTo] = useState("");
  const [newTaskAdditionalAssignees, setNewTaskAdditionalAssignees] = useState([]);
  const [editingTaskIndex, setEditingTaskIndex] = useState(null);
  const [editedTaskText, setEditedTaskText] = useState("");
  const [editedTaskAssignedTo, setEditedTaskAssignedTo] = useState("");
  const [editedTaskAdditionalAssignees, setEditedTaskAdditionalAssignees] = useState([]);
  const [showTemplateDialog, setShowTemplateDialog] = useState(false);
  const [addingSubTaskFor, setAddingSubTaskFor] = useState(null);
  const [newSubTaskText, setNewSubTaskText] = useState("");
  const [showDriveBrowser, setShowDriveBrowser] = useState(false);
  const [addingDetailFor, setAddingDetailFor] = useState(null); // { taskIndex, subTaskIndex }
  const [newDetailText, setNewDetailText] = useState("");
  const [showCreateRiderDialog, setShowCreateRiderDialog] = useState(false);
  const [showDuplicateForm, setShowDuplicateForm] = useState(false);
  const [duplicateData, setDuplicateData] = useState(null);

  useEffect(() => {
    if (isOpen && workOrder) {
      loadRelatedData();
    }
  }, [isOpen, workOrder]);

  useEffect(() => {
    if (!isOpen || !sessionToken) {
      setAllUsers([]);
      return;
    }

    let cancelled = false;
    loadAuthorizedUserDirectory({ sessionToken })
      .then((directory) => {
        if (!cancelled) setAllUsers(directory.users);
      })
      .catch((error) => {
        if (!cancelled) {
          setAllUsers([]);
          console.error("Error loading Work Order assignment users:", error);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [isOpen, sessionToken]);

  const loadRelatedData = async () => {
    setRelatedDataReadError("");
    setRelatedDataVerified(false);
    try {
      const all = await loadAllEntityRows({
        entity: WorkOrder,
        query: { completed: false, deleted: { $ne: true } },
        sort: "created_date",
        label: "Work Order Details related Work Orders"
      });
      setAllWorkOrders(all);

      // Find riders
      if (!workOrder.is_rider) {
        const foundRiders = all.filter(
          (wo) => wo.parent_work_order_id === workOrder.id && wo.is_rider
        );
        setRiders(foundRiders);
      } else {
        setRiders([]);
      }

      // Find parent
      if (workOrder.is_rider && workOrder.parent_work_order_id) {
        const parent = all.find((wo) => wo.id === workOrder.parent_work_order_id);
        setParentWorkOrder(parent || null);
      } else {
        setParentWorkOrder(null);
      }

      // Load dependencies (from workOrder data)
      setDependencies(workOrder.dependencies || []);
      setRelatedDataVerified(true);
    } catch (error) {
      console.error("Could not verify related Work Orders:", error);
      setAllWorkOrders([]);
      setRiders([]);
      setParentWorkOrder(null);
      setDependencies(workOrder.dependencies || []);
      setRelatedDataReadError(error?.message || "Related Work Orders could not be verified completely.");
    }
  };

  const handleAddDependency = async () => {
    if (!newDependency.trigger_value || !newDependency.action_value) return;

    const dependencyToAdd = { ...newDependency, id: Date.now() };
    setInlineEditError("");
    try {
      const saved = await mutateWorkOrderArrayField({
        workOrderId: workOrder.id,
        field: "dependencies",
        label: "Work Order dependency",
        mutate: (currentDependencies) => [...currentDependencies, dependencyToAdd],
      });
      const savedDependencies = saved.dependencies || [];
      setDependencies(savedDependencies);
      Object.assign(workOrder, { dependencies: savedDependencies, updated_date: saved.updated_date });
      setIsEditingDependency(false);
      setNewDependency({
        trigger_type: "stage_change",
        trigger_value: "",
        action_type: "move_stage",
        action_value: "",
        target_work_order_id: ""
      });
      if (onUpdate) onUpdate();
    } catch (error) {
      console.error("Could not add Work Order dependency safely:", error);
      setInlineEditError(error?.message || "Dependencies changed in another session. Reload before adding this dependency.");
    }
  };

  const handleDeleteDependency = async (depId) => {
    const dependencyToDelete = dependencies.find((dependency) => dependency.id === depId);
    if (!dependencyToDelete) {
      setInlineEditError("The dependency could not be identified safely. Reload before deleting it.");
      return;
    }

    setInlineEditError("");
    try {
      const saved = await mutateLocatedWorkOrderArrayItem({
        workOrderId: workOrder.id,
        field: "dependencies",
        item: dependencyToDelete,
        remove: true,
        label: "Work Order dependency",
      });
      const savedDependencies = saved.dependencies || [];
      setDependencies(savedDependencies);
      Object.assign(workOrder, { dependencies: savedDependencies, updated_date: saved.updated_date });
      if (onUpdate) onUpdate();
    } catch (error) {
      console.error("Could not delete Work Order dependency safely:", error);
      setInlineEditError(error?.message || "Dependencies changed in another session. Reload before deleting this dependency.");
    }
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const expectedImageUrl = workOrder.image_url;
    setUploading(true);
    try {
      const result = await UploadFile({ file });
      const saved = await replaceWorkOrderFieldsIfUnchanged({
        workOrderId: workOrder.id,
        expectedFields: { image_url: expectedImageUrl },
        nextFields: { image_url: result.file_url },
        label: "Work Order details image replacement",
      });
      Object.assign(workOrder, { image_url: saved.image_url, updated_date: saved.updated_date });
      await ActivityActions.imageUploaded(workOrder);
      if (onUpdate) onUpdate();
    } catch (error) {
      console.error("Error uploading Work Order image:", error);
      setInlineEditError(error?.message || "This Work Order image changed in another session. Reload and try the upload again.");
      if (onUpdate) onUpdate();
    } finally {
      setUploading(false);
    }
  };

  const startEdit = (field) => {
    inlineEditBaselineRef.current[field] = workOrder[field];
    setInlineEditError("");
    setEditingField(field);
    setEditValues({
      title: workOrder.title,
      client_name: workOrder.client_name,
      description: workOrder.description,
      assigned_to: workOrder.assigned_to,
      due_date: workOrder.due_date,
      start_date: workOrder.start_date,
      google_drive_folder_url: workOrder.google_drive_folder_url
    });
  };

  const saveEdit = async (field) => {
    // A duplicate submission would CAS-fail against this request's own write
    // and report a spurious "changed in another session" conflict.
    if (inlineEditSavingRef.current.has(field)) return;
    inlineEditSavingRef.current.add(field);
    const oldValue = Object.prototype.hasOwnProperty.call(inlineEditBaselineRef.current, field)
      ? inlineEditBaselineRef.current[field]
      : workOrder[field];
    const newValue = editValues[field];
    setInlineEditError("");
    try {
      const saved = await replaceWorkOrderFieldsIfUnchanged({
        workOrderId: workOrder.id,
        expectedFields: { [field]: oldValue },
        nextFields: { [field]: newValue },
        label: `Work Order ${field}`,
      });
      await ActivityActions.fieldUpdated(workOrder, field, oldValue, saved[field]);
      Object.assign(workOrder, { [field]: saved[field], updated_date: saved.updated_date });
      delete inlineEditBaselineRef.current[field];
      setEditingField(null);

      // Don't refresh the entire page for google drive URL changes
      if (field !== 'google_drive_folder_url') {
        if (onUpdate) await onUpdate();
        await loadRelatedData();
      }
    } catch (error) {
      console.error(`Could not save Work Order ${field}:`, error);
      setInlineEditError(error?.message || "This Work Order field changed in another session. Reload the latest value before saving.");
    } finally {
      inlineEditSavingRef.current.delete(field);
    }
  };

  const cancelEdit = () => {
    if (editingField) delete inlineEditBaselineRef.current[editingField];
    setInlineEditError("");
    setEditingField(null);
    setEditValues({});
  };

  const reloadInlineEditLatest = async () => {
    try {
      const latest = await WorkOrder.get(workOrder.id);
      if (!latest?.id) throw new Error("The latest Work Order could not be found.");
      Object.assign(workOrder, latest);
      inlineEditBaselineRef.current = {};
      setEditingField(null);
      setEditValues({});
      setInlineEditError("");
      if (onUpdate) await onUpdate(latest);
      await loadRelatedData();
    } catch (error) {
      console.error("Could not reload latest Work Order inline-edit data:", error);
      setInlineEditError(error?.message || "The latest Work Order could not be loaded. No unsaved value was written.");
    }
  };

  const handleToggleTask = async (taskIndex) => {
    const task = tasks[taskIndex];
    if (!task) return;
    const taskText = task.text;
    const wasCompleted = !!task.completed;
    const targetCompleted = !wasCompleted;
    try {
      const saved = await mutateLocatedWorkOrderArrayItem({
        workOrderId: workOrder.id,
        field: "notes",
        item: task,
        label: "Work Order task",
        mutateItem: (currentTask) => ({ ...currentTask, completed: targetCompleted }),
      });
      Object.assign(workOrder, { notes: saved.notes || [], updated_date: saved.updated_date });
      if (onUpdate) onUpdate();
      if (wasCompleted) {
        await ActivityActions.taskUncompleted(workOrder, taskText);
      } else {
        await ActivityActions.taskCompleted(workOrder, taskText);
      }
    } catch (error) {
      console.error('Failed to toggle task:', error);
      alert('Failed to toggle task: ' + (error?.message || error));
    }
  };

  const handleAddTask = async () => {
    if (!newTaskText.trim()) return;
    const newTask = {
      id: Date.now().toString(),
      text: newTaskText,
      timestamp: new Date().toISOString(),
      created_by: currentUser?.full_name || currentUser?.email || "Unknown",
      assigned_to: newTaskAssignedTo || "",
      additional_assignees: newTaskAdditionalAssignees || [],
      completed: false,
      sub_tasks: [],
      depends_on: [],
      estimated_hours: 0,
      is_milestone: false
    };
    try {
      const saved = await mutateWorkOrderArrayField({
        workOrderId: workOrder.id,
        field: "notes",
        label: "Work Order tasks",
        mutate: (currentTasks) => currentTasks.some((task) => task?.id === newTask.id)
          ? currentTasks
          : [...currentTasks, newTask],
      });
      Object.assign(workOrder, { notes: saved.notes || [], updated_date: saved.updated_date });
      setNewTaskText("");
      setNewTaskAssignedTo("");
      setNewTaskAdditionalAssignees([]);
      setIsAddingTask(false);
      if (onUpdate) onUpdate();
      await ActivityActions.taskAdded(workOrder, newTaskText);
    } catch (error) {
      console.error('Failed to add task:', error);
      alert('Failed to add task: ' + (error?.message || error));
    }
  };

  const [newSubTaskAssignedTo, setNewSubTaskAssignedTo] = useState("");
  const [newSubTaskAdditionalAssignees, setNewSubTaskAdditionalAssignees] = useState([]);
