                          {note.type === 'vinyl' && 'Vinyl'}
                          {note.type === 'permitting' && 'Permit'}
                          {note.type === 'design' && 'Design'}
                          {note.type === 'installation' && 'Install'}
                          {note.type === 'client' && 'Client'}
                          {note.type === 'other' && 'Other'}
                        </Badge>
                      </td>
                      <td className="px-2 py-1.5 text-gray-500">
