                  <PopoverContent className="clay-card w-80">
                    <Label>Start Date</Label>
                    <div className="flex gap-2 mt-2 mb-3">
                      <CcsDateField
                        value={editValues.start_date || workOrder.start_date || ''}
                        onChange={(e) => setEditValues({ ...editValues, start_date: e.target.value })} />
                      <Button size="sm" onClick={() => saveEdit('start_date')}>
                        <Check className="w-4 h-4" />
                      </Button>
                    </div>
                    <Label>Due Date</Label>
                    <div className="flex gap-2 mt-2">
                      <CcsDateField
                        value={editValues.due_date || workOrder.due_date || ''}
                        onChange={(e) => setEditValues({ ...editValues, due_date: e.target.value })} />
                      <Button size="sm" onClick={() => saveEdit('due_date')}>
                        <Check className="w-4 h-4" />
                      </Button>
                    </div>
                  </PopoverContent>
                </Popover>
              </div>
            )}
            {/* Three column layout */}
            <div className="grid grid-cols-3 gap-6 mb-6">

              {/* Left Column - Core Info */}
              <div className="space-y-4">
                {/* Image - Editable */}
                <Popover>
                  <PopoverTrigger asChild>
                    <div className="rounded-xl overflow-hidden cursor-pointer hover:opacity-80 transition-opacity" style={{
                      background: 'linear-gradient(135deg, rgba(255,255,255,0.9) 0%, rgba(240,240,240,0.8) 100%)',
                      boxShadow: 'inset 2px 2px 4px rgba(0,0,0,0.1)'
                    }}>
                      {workOrder.image_url ?
                      <img src={workOrder.image_url} alt={workOrder.title} className="w-full h-48 object-contain" /> :

                      <div className="w-full h-48 flex items-center justify-center">
                          <Upload className="w-12 h-12 text-gray-400" />
                        </div>
                      }
                    </div>
                  </PopoverTrigger>
                  <PopoverContent className="clay-card w-64">
                    <Label>Upload New Image</Label>
                    <input
                      type="file"
                      accept="image/*"
                      onChange={handleImageUpload}
                      className="mt-2 text-sm"
                      disabled={uploading} />

                    {uploading && <p className="text-xs text-gray-500 mt-2">Uploading...</p>}
                  </PopoverContent>
                </Popover>

                {/* Basic Info - Editable */}
                <div className="clay-card p-4 space-y-3">
                  <Popover>
                    <PopoverTrigger asChild>
                      <div className="flex items-center gap-2 text-sm cursor-pointer hover:bg-white/50 p-2 rounded transition-colors">
                        <Calendar className="w-4 h-4 text-orange-600" />
                        <span className="font-medium">Due:</span>
                        <span className="text-gray-600">
                          {workOrder.due_date ? format(parseLocalDate(workOrder.due_date), "MMM d, yyyy") : 'No due date'}
                        </span>
                      </div>
                    </PopoverTrigger>
                    <PopoverContent className="clay-card w-64">
                      <Label>Due Date</Label>
                      <div className="flex gap-2 mt-2">
                        <CcsDateField
                          value={editValues.due_date || workOrder.due_date || ''}
                          onChange={(e) => setEditValues({ ...editValues, due_date: e.target.value })} />

                        <Button size="sm" onClick={() => saveEdit('due_date')}>
                          <Check className="w-4 h-4" />
                        </Button>
                      </div>
                    </PopoverContent>
                  </Popover>

                  <div className="flex items-center gap-2 text-sm p-2">
                    <FileText className="w-4 h-4 text-purple-600" />
                    <span className="font-medium">Stage:</span>
                    <Badge style={{ backgroundColor: stageColors[workOrder.current_stage] }}>
                      {stageDisplayNames[workOrder.current_stage]}
                    </Badge>
                  </div>
                </div>

                {/* Milestones */}
                <div className="clay-card p-4">
                  <MilestoneManager
                    milestones={workOrder.milestones || []}
                    tasks={tasks}
                    onUpdate={async (newMilestones) => {
                      setInlineEditError("");
                      try {
                        const saved = await replaceWorkOrderArrayFieldIfUnchanged({
                          workOrderId: workOrder.id,
                          field: "milestones",
                          expectedArray: workOrder.milestones || [],
                          nextArray: newMilestones,
                          label: "Work Order milestones",
                        });
                        Object.assign(workOrder, {
                          milestones: saved.milestones || [],
                          updated_date: saved.updated_date,
                        });
                        if (onUpdate) onUpdate();
                      } catch (error) {
                        console.error("Could not update Work Order milestones safely:", error);
                        setInlineEditError(error?.message || "Milestones changed in another session. Reload before saving this milestone change.");
                      }
                    }}
                    compact
                  />
                </div>

                {/* Relationships */}
                <div className="clay-card p-4">
                  <h3 className="font-semibold text-sm mb-3">Relationships</h3>

                  {parentWorkOrder &&
                  <div className="mb-3">
                      <p className="text-xs text-gray-500 mb-1">Parent Work Order</p>
                      <Link to={createPageUrl(getPageNameForStage(parentWorkOrder.current_stage))}>
                        <div className="clay-button p-2 rounded-lg flex items-center gap-2 hover:opacity-80 transition-opacity">
                          <LinkIcon className="w-4 h-4 text-blue-600" />
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium truncate">{parentWorkOrder.title}</p>
                            <p className="text-xs text-gray-500">{parentWorkOrder.client_name}</p>
                          </div>
                        </div>
                      </Link>
                    </div>
                  }

                  {riders.length > 0 &&
                  <div>
                      <p className="text-xs text-gray-500 mb-1">Riders ({riders.length})</p>
                      <div className="space-y-1">
                        {riders.map((rider) =>
                      <Link key={rider.id} to={createPageUrl(getPageNameForStage(rider.rider_stage || rider.current_stage))}>
                            <div className="clay-button p-2 rounded-lg flex items-center gap-2 hover:opacity-80 transition-opacity">
                              <LinkIcon className="w-4 h-4 text-purple-600" />
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium truncate">{rider.title}</p>
                                <p className="text-xs text-gray-500">Stage: {stageDisplayNames[rider.current_stage]}</p>
                              </div>
                            </div>
                          </Link>
                      )}
                      </div>
                    </div>
                  }

                  {!parentWorkOrder && riders.length === 0 &&
                  <p className="text-xs text-gray-400 text-center py-2">No relationships</p>
                  }
                </div>
              </div>

              {/* Middle Column - Description and Google Drive */}
              <div className="space-y-4">
                {/* Description - Editable */}
                <Popover>
                  <PopoverTrigger asChild>
                    <div className="clay-card p-4 cursor-pointer hover:shadow-lg transition-shadow">
                      <h3 className="font-semibold text-sm mb-2">Description</h3>
                      <p className="text-sm text-gray-600 leading-relaxed">{workOrder.description || 'Click to add description'}</p>
                    </div>
                  </PopoverTrigger>
                  <PopoverContent className="clay-card w-80">
                    <Label>Description</Label>
                    <Textarea
                      value={editValues.description || workOrder.description || ''}
                      onChange={(e) => setEditValues({ ...editValues, description: e.target.value })}
                      className="mt-2 min-h-24" />

                    <Button size="sm" className="mt-2" onClick={() => saveEdit('description')}>
                      Save
                    </Button>
                  </PopoverContent>
                </Popover>

                {/* Uploaded Files */}
                <WorkOrderFiles workOrder={workOrder} onUpdate={onUpdate} />

                {/* Google Drive - Compact */}
                <div className="clay-card p-3">
                  <div className="flex items-center justify-between">
                    <h3 className="font-semibold text-sm flex items-center gap-2">
                      <FolderOpen className="w-4 h-4 text-green-600" />
                      Google Drive
                    </h3>
                    <Button 
                      size="sm" 
                      variant="ghost" 
                      onClick={() => startEdit('google_drive_folder_url')}
                      className="h-6 px-2 text-xs"
                    >
                      <Pencil className="w-3 h-3 mr-1" />
                      {workOrder.google_drive_folder_url ? 'Edit' : 'Link'}
                    </Button>
                  </div>
                  {editingField === 'google_drive_folder_url' ? (
                    <div className="space-y-2 mt-2">
                      <Input
                        value={editValues.google_drive_folder_url || ''}
                        onChange={(e) => setEditValues({ ...editValues, google_drive_folder_url: e.target.value })}
                        placeholder="https://drive.google.com/drive/folders/..."
                        className="text-sm"
                      />
                      <div className="flex gap-2">
                        <Button size="sm" onClick={() => saveEdit('google_drive_folder_url')}>
                          <Check className="w-4 h-4 mr-1" />
                          Save
                        </Button>
                        <Button size="sm" variant="ghost" onClick={cancelEdit}>
                          <X className="w-4 h-4" />
                        </Button>
                      </div>
                    </div>
                  ) : workOrder.google_drive_folder_url ? (
                    <Button
                      onClick={() => openExternalHttpUrl(workOrder.google_drive_folder_url)}
                      disabled={!safeExternalHttpUrl(workOrder.google_drive_folder_url)}
                      className="w-full mt-2 gap-2"
                      size="sm"
                    >
                      <ExternalLink className="w-4 h-4" />
                      Open in Drive
                    </Button>
                  ) : (
                    <p className="text-xs text-gray-400 mt-2 text-center">No folder linked</p>
                  )}
                </div>
              </div>

              {/* Right Column - Actions */}
              <div className="space-y-4">
                <div className="clay-card p-4">
                  <h3 className="font-semibold text-sm mb-2">Actions</h3>
                  <div className="space-y-2">
                    {!workOrder.is_rider && (
                    <Button
                      className="w-full justify-start clay-button"
                      variant="ghost"
                      onClick={() => setShowCreateRiderDialog(true)}>

                        <Plus className="w-4 h-4 mr-2" />
                        Create Rider
                      </Button>
                    )}

                    {onComplete && !workOrder.completed &&
                    <Button
                      className="w-full justify-start clay-button"
                      variant="ghost"
                      onClick={() => setShowCompleteConfirm(true)}>

                        <CheckCircle className="w-4 h-4 mr-2 text-green-600" />
                        Mark Complete
                      </Button>
                    }

                    <Button
                      className="w-full justify-start clay-button"
                      variant="ghost"
                      onClick={() => window.open(`/WorkOrderTraveler?wo=${encodeURIComponent(workOrder.id)}`, "_blank")}>
                      <FileText className="w-4 h-4 mr-2 text-violet-600" />
                      Print Traveler
                    </Button>

                    <Button
                      className="w-full justify-start clay-button"
                      variant="ghost"
                      disabled={!relatedDataVerified}
                      title={!relatedDataVerified ? "Related Work Orders must be verified before duplicate checking is available." : undefined}
                      onClick={() => {
                        // Copy all fields from current work order for duplicating
                        const { id, created_date, updated_date, created_by, notes, work_notes, follow_up, ...dataWithoutId } = workOrder;
                        setDuplicateData({
                          ...dataWithoutId,
                          title: "", // Clear title so user must enter new one
                          description: "", // Clear description
                          notes: [],
                          work_notes: [],
                          follow_up: [],
                          current_stage: "estimating"
                        });
                        setShowDuplicateForm(true);
                      }}>
                      <Copy className="w-4 h-4 mr-2 text-blue-600" />
                      Duplicate Client
                    </Button>

                    <Button
                      className="w-full justify-start clay-button text-red-600 hover:text-red-700"
                      variant="ghost"
                      onClick={handleDeleteWorkOrder}>

                      <Trash2 className="w-4 h-4 mr-2" />
                      Delete {workOrder.is_rider ? 'Rider' : 'Work Order'}
                    </Button>
                  </div>
                </div>

                {/* Restore Options (for completed work orders) */}
                {onRestore && workOrder.completed &&
                <div className="clay-card p-4">
                    <h3 className="font-semibold text-sm mb-3">Restore to Stage</h3>
                    <div className="grid grid-cols-2 gap-2">
                      {['permitting', 'design', 'production', 'fabrication', 'installation'].map((stage) =>
                    <Button
                      key={stage}
                      className="clay-button text-xs justify-start"
                      variant="ghost"
                      size="sm"
                      onClick={() => {onRestore(workOrder, stage);onClose();}}>

                          <ArrowRight className="w-3 h-3 mr-1" />
                          {stageDisplayNames[stage]}
                        </Button>
                    )}
                    </div>
                  </div>
                }

              </div>
              </div>

            {/* Time Entries Section - Full Width at Bottom */}
            <div className="clay-card p-4 mb-6">
              <WorkOrderTimeEntries 
                workOrderId={workOrder.id}
                workOrderTitle={workOrder.title}
              />
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
        <AlertDialogContent className="clay-card border-none">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {workOrder.is_rider ? 'Rider' : 'Work Order'}?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete "{workOrder.title}"? It will be moved to Project Trash and can be recovered until it is permanently deleted there.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="clay-button">Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmDelete} disabled={deletingWorkOrder} className="bg-red-600 text-white">
              {deletingWorkOrder ? "Deleting…" : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Complete Confirmation Dialog */}
      <AlertDialog open={showCompleteConfirm} onOpenChange={setShowCompleteConfirm}>
        <AlertDialogContent className="clay-card border-none">
          <AlertDialogHeader>
            <AlertDialogTitle>Mark as Complete?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to mark "{workOrder.title}" as complete?
              <br /><br />
              This will send an email notification to the team.
            </AlertDialogDescription>
          </AlertDialogHeader>

          {openProducts.length > 0 && (
            <div className="mx-1 mb-2 rounded border border-amber-200 bg-amber-50 p-2.5 text-xs text-amber-800">
              <span className="font-semibold">
                {openProducts.length} product{openProducts.length === 1 ? "" : "s"} still open:
              </span>
              <ul className="mt-1 list-disc pl-4">
                {openProducts.slice(0, 6).map((p) => (
                  <li key={p.id || p.name}>
                    {p.name}{p.status !== "none" ? ` (${p.status.replace(/_/g, " ")})` : ""}
                  </li>
                ))}
              </ul>
              {openProducts.length > 6 && <div className="mt-1">+{openProducts.length - 6} more</div>}
            </div>
          )}
          <AlertDialogFooter>
            <AlertDialogCancel className="clay-button">Cancel</AlertDialogCancel>
            <AlertDialogAction 
              onClick={() => {
                if (onComplete) onComplete(workOrder);
                setShowCompleteConfirm(false);
                onClose();
              }} 
              className="bg-green-600 text-white hover:bg-green-700">
              Mark Complete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Task Template Dialog */}
      <TaskTemplateDialog
        isOpen={showTemplateDialog}
        onClose={() => setShowTemplateDialog(false)}
        onUseTemplate={async (template) => {
          const templateBatchId = `${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
          const newTasks = template.tasks.map((t, taskIndex) => ({
            id: `template_${templateBatchId}_${taskIndex}`,
            text: t.text,
            timestamp: new Date().toISOString(),
            created_by: "Template",
            completed: false,
            sub_tasks: (t.sub_tasks || []).map(st => ({
              text: typeof st === 'string' ? st : (st.text || ''),
              completed: false,
              details: (typeof st === 'object' && st.details) ? st.details.map(d => ({ text: d, completed: false })) : []
            }))
          }));
          const newTaskIds = new Set(newTasks.map((task) => task.id));
          try {
            const saved = await mutateWorkOrderArrayField({
              workOrderId: workOrder.id,
              field: "notes",
              label: "Work Order template tasks",
              mutate: (currentTasks) => {
                const existingIds = new Set(currentTasks.map((task) => task?.id).filter(Boolean));
                const missing = newTasks.filter((task) => newTaskIds.has(task.id) && !existingIds.has(task.id));
                return missing.length > 0 ? [...currentTasks, ...missing] : currentTasks;
              },
            });
            Object.assign(workOrder, { notes: saved.notes || [], updated_date: saved.updated_date });
            setShowTemplateDialog(false);
          } catch (error) {
            console.error('Failed to apply template:', error);
            alert('Failed to apply template: ' + (error?.message || error));
          }
        }}
      />

      {/* Create Rider Dialog */}
      <CreateRiderDialog
        isOpen={showCreateRiderDialog}
        onClose={() => setShowCreateRiderDialog(false)}
        parentWorkOrder={workOrder}
        onCreated={(rider) => {
          if (onUpdate) onUpdate();
          loadRelatedData();
        }}
      />

      {/* Duplicate Client - Full Form */}
      {showDuplicateForm && (
        <WorkOrderForm
          key={workOrder.id + '-duplicate'}
          isOpen={showDuplicateForm}
          onClose={() => { setShowDuplicateForm(false); setDuplicateData(null); }}
          onSave={async (data) => {
            await createWorkOrderWithRecovery({ data, label: "Duplicated Work Order" });
            setShowDuplicateForm(false);
            setDuplicateData(null);
            try {
              if (onUpdate) await onUpdate();
            } catch (refreshError) {
              console.error("Duplicated Work Order was saved but refresh failed:", refreshError);
              setInlineEditError("The duplicated Work Order was saved successfully, but the screen could not finish refreshing. Do not duplicate it again; reload to see the saved job.");
            }
          }}
          initialData={duplicateData}
          existingWorkOrders={allWorkOrders}
        />
      )}

      {/* Google Drive File Browser */}
      <GoogleDriveFileBrowser
        isOpen={showDriveBrowser}
        onClose={() => setShowDriveBrowser(false)}
        folderUrl={workOrder.google_drive_folder_url}
        workOrderTitle={workOrder.title}
        onFileIdsUpdate={async (fileId) => {
          setInlineEditError("");
          try {
            const saved = await mutateWorkOrderArrayField({
              workOrderId: workOrder.id,
              field: "google_drive_file_ids",
              label: "Work Order Google Drive file links",
              mutate: (currentIds) => currentIds.includes(fileId) ? currentIds : [...currentIds, fileId],
            });
            Object.assign(workOrder, {
              google_drive_file_ids: saved.google_drive_file_ids || [],
              updated_date: saved.updated_date,
            });
            if (onUpdate) onUpdate();
          } catch (error) {
            console.error("Could not link Google Drive file safely:", error);
            setInlineEditError(error?.message || "Google Drive file links changed in another session. Reload before linking this file.");
          }
        }}
      />
    </>);

}

import { useState, useEffect } from "react";
import { staffEntities } from "@/components/staff/staffEntities";
import DragDropList from "../components/workflow/DragDropList";
import StageTasksPanel from "@/components/workflow/StageTasksPanel";
import WorkOrderForm from "../components/workflow/WorkOrderForm";
import { ActivityActions } from "../components/workflow/ActivityLogger";
import { useAuth } from "@/components/auth/EmailGate";
import { useAllWorkOrders, fetchAllWorkOrders } from "@/lib/workOrderCache";
import { createWorkOrderWithRecovery, softDeleteWorkOrderFromLoadedSnapshot, transitionWorkOrderFromLoadedSnapshot, updateWorkOrderFromLoadedSnapshot } from "@/components/workflow/workOrderPersistence";
import { reorderWorkOrdersFromLoadedSnapshot } from "@/components/workflow/workOrderPriorityPersistence";
import { NotificationTriggers } from "@/components/workflow/NotificationService";

const WorkOrder = staffEntities.WorkOrder;

export default function InstallationDeliver() {
  const [workOrders, setWorkOrders] = useState([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingWorkOrder, setEditingWorkOrder] = useState(null);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [riderConfig, setRiderConfig] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isReordering, setIsReordering] = useState(false);
  const { currentUser, isRegistered, promptForEmail } = useAuth();

  useEffect(() => {
    document.title = "Installation - Workflow Manager";
  }, []);

  const { data: cachedWorkOrders = [], isFetched: workOrdersFetched } = useAllWorkOrders();

  useEffect(() => {
    const taskDescriptions = getInstallationTaskDescriptions();
    setWorkOrders((cachedWorkOrders || []).filter(wo =>
      wo.completed !== true && wo.deleted !== true &&
      ((wo.current_task_description && taskDescriptions.some(desc =>
        wo.current_task_description.includes(desc)
      )) || (wo.is_rider && wo.rider_stage === 'installation' && wo.in_pipeline !== false))
    ).sort((a, b) => (a.priority || 0) - (b.priority || 0)));
  }, [cachedWorkOrders]);

  useEffect(() => {
    if (workOrdersFetched) setIsLoading(false);
  }, [workOrdersFetched]);

  useEffect(() => {
    loadWorkOrders(true);

    const handleFullscreenChange = () => {
      setIsFullScreen(!!document.fullscreenElement);
    };
    const handleKeyDown = (e) => {
      if (e.key === 'Escape' && document.fullscreenElement) {
        document.exitFullscreen();
      }
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  // Get task descriptions mapped to Installation page from localStorage
  const getInstallationTaskDescriptions = () => {
    try {
      const saved = localStorage.getItem('salesTaskDescriptions');
      if (saved) {
        const parsed = JSON.parse(saved);
        return parsed
          .filter(item => item.page === "Installation")
          .map(item => item.text || item);
      }
    } catch {}
    return ["WIP - Installation", "WIP - Outsourced Installation"];
  };

  const fetchWorkOrders = async () => {
    const allWorkOrders = await fetchAllWorkOrders();
    const taskDescriptions = getInstallationTaskDescriptions();
    return allWorkOrders.filter(wo =>
      wo.completed !== true && wo.deleted !== true &&
      ((wo.current_task_description && taskDescriptions.some(desc =>
        wo.current_task_description.includes(desc)
      )) || (wo.is_rider && wo.rider_stage === 'installation' && wo.in_pipeline !== false))
    ).sort((a, b) => (a.priority || 0) - (b.priority || 0));
  };

  const loadWorkOrders = async (showLoading = false) => {
    if (showLoading) setIsLoading(true);
    try {
      setWorkOrders(await fetchWorkOrders());
    } catch (error) {
      console.error("Error loading work orders:", error);
    } finally {
      if (showLoading) setIsLoading(false);
    }
  };

  const handleReorder = async (reorderedItems) => {
    if (!isRegistered) { promptForEmail(); return; }
    if (isReordering) return;

    const loadedItems = workOrders;
    setWorkOrders(reorderedItems);
    setIsReordering(true);
    try {
      const result = await reorderWorkOrdersFromLoadedSnapshot({
        entity: WorkOrder,
        loadedItems,
        reorderedItems,
        readCurrentItems: fetchWorkOrders,
        label: "Installation priority reorder",
      });
      setWorkOrders(result.items);
      NotificationTriggers.workOrderPriorityReordered(loadedItems, reorderedItems, currentUser?.full_name || currentUser?.email)
        .catch((e) => console.error("Priority-change notification failed:", e));
    } catch (error) {
      console.error("Error reordering work orders:", error);
      alert(error?.message || "The Installation priority order changed in another session. Reload and try the reorder again.");
      await loadWorkOrders();
    } finally {
      setIsReordering(false);
    }
  };

  const handleSave = async (formData) => {
    if (!isRegistered) { promptForEmail(); return; }
    try {
      if (editingWorkOrder) {
        await updateWorkOrderFromLoadedSnapshot({ workOrder: editingWorkOrder, formData, label: "Installation Work Order" });
      } else {
        const maxPriority = workOrders.length > 0
          ? Math.max(...workOrders.map(wo => wo.priority || 0))
          : -1;
        const { record: created } = await createWorkOrderWithRecovery({
          data: { ...formData, priority: maxPriority + 1 },
          label: riderConfig ? "Installation rider Work Order" : "Installation Work Order",
        });
        try {
          if (riderConfig) {
            await ActivityActions.riderCreated(created, riderConfig.parentWorkOrder.title);
          } else {
            await ActivityActions.workOrderCreated(created);
          }
        } catch (activityError) {
          console.error("Work Order was saved but its activity notification failed:", activityError);
          alert("The Work Order was saved successfully, but its activity notification could not be completed. Do not create the Work Order again; reload to see the saved job.");
        }
      }
      setEditingWorkOrder(null);
      setRiderConfig(null);
      loadWorkOrders();
    } catch (error) {
      console.error("Error saving work order:", error);
      throw error;
    }
  };

  const handleMove = async (workOrder, newStage) => {
    if (!isRegistered) { promptForEmail(); return; }
    try {
      const oldStage = workOrder.current_stage;
      await transitionWorkOrderFromLoadedSnapshot({
        workOrder,
        newStage,
        normalizeLegacyNotes: true,
        label: "Installation stage transition",
      });
      await ActivityActions.stageChanged(workOrder, oldStage, newStage);
      loadWorkOrders();
    } catch (error) {
      console.error("Error moving:", error);
      alert(error?.message || "This Work Order changed in another session. Reload and try the transition again.");
      loadWorkOrders();
    }
  };

  const handleEdit = (workOrder) => {
    if (!isRegistered) { promptForEmail(); return; }
    setEditingWorkOrder(workOrder);
    setRiderConfig(null);
    setIsFormOpen(true);
  };

  const handleSplit = (workOrder) => {
    if (!isRegistered) { promptForEmail(); return; }
    setRiderConfig({ parentWorkOrder: workOrder, stage: 'installation' });
    setEditingWorkOrder(null);
    setIsFormOpen(true);
  };

  const handleComplete = async (workOrder) => {
    if (!isRegistered) { promptForEmail(); return; }
    try {
      await transitionWorkOrderFromLoadedSnapshot({
        workOrder,
        newStage: "completed",
        completed: true,
        normalizeLegacyNotes: true,
        label: "Installation completion",
      });
      await ActivityActions.workOrderCompleted(workOrder);
      loadWorkOrders();
    } catch (error) {
      console.error("Error completing work order:", error);
      alert(error?.message || "This Work Order changed in another session. Reload and try the transition again.");
      loadWorkOrders();
    }
  };
  const handleDelete = async (workOrder) => {
    if (!isRegistered) { promptForEmail(); return; }
    try {
      const deleted = await softDeleteWorkOrderFromLoadedSnapshot({
        workOrder,
        deletedBy: currentUser?.email || "unknown",
        label: "Installation Work Order delete",
      });
      Object.assign(workOrder, deleted);
      await ActivityActions.workOrderDeleted(workOrder);
      loadWorkOrders();
    } catch (error) {
      console.error("Error deleting work order:", error);
      alert(error?.message || "This Work Order changed in another session. Reload before deleting it.");
      loadWorkOrders();
    }
  };

  const handleDoubleClick = (e) => {
    if (isFullScreen && e.target.closest('.clay-card') === null) {
      document.exitFullscreen();
    }
  };

  return (
    <div className="min-h-screen p-4" onDoubleClick={handleDoubleClick}>
      {isFullScreen && (
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 bg-black/70 text-white px-4 py-2 rounded-lg text-sm z-50 pointer-events-none">
          To exit press ESC
        </div>
      )}
      <div className="w-full max-w-[95vw] mx-auto">
        <StageTasksPanel stage="installation" />

        <div className="clay-card">
          {isLoading ? (
            <div className="text-center py-12">
              <p className="text-gray-500 text-lg">Loading...</p>
            </div>
          ) : (
            <DragDropList
              workOrders={workOrders}
              onReorder={handleReorder}
              reorderDisabled={isReordering}
              onEdit={handleEdit}
              onMove={handleMove}
              onSplit={handleSplit}
              onComplete={handleComplete}
              onUpdate={loadWorkOrders}
              onDelete={handleDelete}
            />
          )}
        </div>
      </div>

      <WorkOrderForm
        isOpen={isFormOpen}
        onClose={() => {
          setIsFormOpen(false);
          setEditingWorkOrder(null);
          setRiderConfig(null);
        }}
        onSave={handleSave}
        workOrder={editingWorkOrder}
        isRider={!!riderConfig}
        parentWorkOrder={riderConfig?.parentWorkOrder}
        lockedStage={riderConfig?.stage}
      />
    </div>
  );
}

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.23';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

const MAX_INLINE_DOWNLOAD_BYTES = 5 * 1024 * 1024;

function bytesToBase64(bytes: Uint8Array) {
  let binary = '';
  const chunkSize = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(offset, Math.min(offset + chunkSize, bytes.length)));
  }
  return btoa(binary);
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const body = await req.json();
    // Shared service Drive token — restrict to admin so the lowest-privilege
    // staff session cannot read/delete arbitrary company Drive files.
    const gdoActor = await authenticateSignShopSession(base44, body?.session_token);
    if (gdoActor?.role !== 'admin') {
      return Response.json({ error: 'Admin access is required for Drive operations.' }, { status: 403 });
    }
    const { action, folderId, fileName, fileContent, fileType, fileId, expectedFileName, expectedModifiedTime } = body;
    const { accessToken } = await base44.asServiceRole.connectors.getConnection("googledrive");

    switch (action) {
      case 'listFiles': {
        // With drive.file scope, we can only list files we created or user granted access to.
        // Validate an optional folder id before interpolating it into Drive's query language.
        const safeFolderId = String(folderId || '').trim();
        if (safeFolderId && !/^[a-zA-Z0-9_-]+$/.test(safeFolderId)) {
          return Response.json({ error: 'Invalid Google Drive folder id' }, { status: 400 });
        }
        let query = "trashed=false";
        if (safeFolderId) {
          query += ` and '${safeFolderId}' in parents`;
        }

        const response = await fetch(
          `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(query)}&fields=files(id,name,mimeType,size,modifiedTime,webViewLink,thumbnailLink,iconLink)&orderBy=folder,name&supportsAllDrives=true&includeItemsFromAllDrives=true`,
          {
            headers: {
              'Authorization': `Bearer ${accessToken}`
            }
          }
        );

        if (!response.ok) {
          await response.text().catch(() => '');
          // If we get a 403, it might be scope limitation.
          if (response.status === 403) {
            return Response.json({ 
              files: [], 
              notice: "Limited access: Can only see files created by this app. Use 'Open in Drive' to view all files." 
            });
          }
          console.error('Failed to list Google Drive files:', response.status);
          return Response.json({ error: 'Failed to list Google Drive files' }, { status: response.status });
        }

        const data = await response.json();
        return Response.json({ files: data.files || [] });
      }

      case 'createFolder': {
        const safeFolderId = String(folderId || '').trim();
        const safeFileName = String(fileName || '').trim();
        if (safeFolderId && !/^[a-zA-Z0-9_-]+$/.test(safeFolderId)) {
          return Response.json({ error: 'Invalid Google Drive parent folder id' }, { status: 400 });
        }
        if (!safeFileName) {
          return Response.json({ error: 'Folder name is required' }, { status: 400 });
        }
        const metadata = {
          name: safeFileName,
          mimeType: 'application/vnd.google-apps.folder',
          parents: safeFolderId ? [safeFolderId] : []
        };

        const response = await fetch(
          'https://www.googleapis.com/drive/v3/files',
          {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${accessToken}`,
              'Content-Type': 'application/json'
            },
            body: JSON.stringify(metadata)
          }
        );

        if (!response.ok) {
          await response.text().catch(() => '');
          console.error('Failed to create Google Drive folder:', response.status);
          return Response.json({ error: 'Failed to create Google Drive folder' }, { status: response.status });
        }

        const folder = await response.json();
        return Response.json({ folder });
      }

      case 'uploadFile': {
        const safeFolderId = String(folderId || '').trim();
        const safeFileName = String(fileName || '').trim();
        if (safeFolderId && !/^[a-zA-Z0-9_-]+$/.test(safeFolderId)) {
          return Response.json({ error: 'Invalid Google Drive parent folder id' }, { status: 400 });
        }
        if (!safeFileName || typeof fileContent !== 'string') {
          return Response.json({ error: 'A file name and file content are required' }, { status: 400 });
        }

        // For multipart upload
        const metadata = {
          name: safeFileName,
          parents: safeFolderId ? [safeFolderId] : []
        };

        // Decode base64 content
        const binaryContent = Uint8Array.from(atob(fileContent), c => c.charCodeAt(0));

        const boundary = '-------314159265358979323846';
        const delimiter = "\r\n--" + boundary + "\r\n";
        const closeDelimiter = "\r\n--" + boundary + "--";

        const metadataStr = JSON.stringify(metadata);

        // Build multipart body
        const encoder = new TextEncoder();
        const part1 = encoder.encode(
          delimiter +
          'Content-Type: application/json; charset=UTF-8\r\n\r\n' +
          metadataStr +
          delimiter +
          'Content-Type: ' + (fileType || 'application/octet-stream') + '\r\n' +
          'Content-Transfer-Encoding: base64\r\n\r\n'
        );
        const part2 = binaryContent;
        const part3 = encoder.encode(closeDelimiter);

        const body = new Uint8Array(part1.length + part2.length + part3.length);
        body.set(part1, 0);
        body.set(part2, part1.length);
        body.set(part3, part1.length + part2.length);

        const response = await fetch(
          'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,mimeType,webViewLink',
          {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${accessToken}`,
              'Content-Type': 'multipart/related; boundary=' + boundary
            },
            body: body
          }
        );

        if (!response.ok) {
          await response.text().catch(() => '');
          console.error('Failed to upload Google Drive file:', response.status);
          return Response.json({ error: 'Failed to upload Google Drive file' }, { status: response.status });
        }

        const file = await response.json();
        return Response.json({ file });
      }

      case 'getDownloadUrl': {
        const safeFileId = String(fileId || '').trim();
        if (!safeFileId || !/^[a-zA-Z0-9_-]+$/.test(safeFileId)) {
          return Response.json({ error: 'Invalid Google Drive file id' }, { status: 400 });
        }

        // Resolve metadata on the server. The browser must never receive the
        // Google OAuth access token just to download a file.
        const response = await fetch(
          `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(safeFileId)}?fields=id,name,mimeType,webViewLink,size`,
          {
            headers: {
              'Authorization': `Bearer ${accessToken}`
            }
          }
        );

        if (!response.ok) {
          await response.text().catch(() => '');
          console.error('Failed to get Google Drive file metadata:', response.status);
          return Response.json({ error: 'Failed to get Google Drive file metadata' }, { status: response.status });
        }

        const file = await response.json();
        const viewUrl = file.webViewLink || `https://drive.google.com/file/d/${encodeURIComponent(safeFileId)}/view`;

        // Google-native files must be opened in Drive. Large regular files also
        // use the Drive view so this JSON function never serializes huge blobs.
        const declaredSize = Number(file.size || 0);
        if (file.mimeType?.startsWith('application/vnd.google-apps') || declaredSize > MAX_INLINE_DOWNLOAD_BYTES) {
          return Response.json({
            url: viewUrl,
            type: 'view',
            fileName: file.name,
            reason: declaredSize > MAX_INLINE_DOWNLOAD_BYTES ? 'large_file' : 'google_native'
          });
        }

        const downloadResponse = await fetch(
          `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(safeFileId)}?alt=media`,
          {
            headers: {
              'Authorization': `Bearer ${accessToken}`
            }
          }
        );

        if (!downloadResponse.ok) {
          await downloadResponse.text().catch(() => '');
          console.error('Failed to download Google Drive file:', downloadResponse.status);
          return Response.json({ error: 'Failed to download Google Drive file' }, { status: downloadResponse.status });
        }

        const bytes = new Uint8Array(await downloadResponse.arrayBuffer());
        if (bytes.byteLength > MAX_INLINE_DOWNLOAD_BYTES) {
          return Response.json({
            url: viewUrl,
            type: 'view',
            fileName: file.name,
            reason: 'large_file'
          });
        }

        return Response.json({
          type: 'download_data',
          fileName: file.name,
          mimeType: file.mimeType || 'application/octet-stream',
          base64: bytesToBase64(bytes)
        });
      }

      case 'deleteFile': {
        const safeFileId = String(fileId || '').trim();
        if (!safeFileId || !/^[a-zA-Z0-9_-]+$/.test(safeFileId)) {
          return Response.json({ error: 'Invalid Google Drive file id' }, { status: 400 });
        }

        const metadataUrl = `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(safeFileId)}?fields=id,name,modifiedTime,trashed&supportsAllDrives=true`;
        const readCurrentFile = async () => {
          const currentResponse = await fetch(metadataUrl, {
            headers: { 'Authorization': `Bearer ${accessToken}` }
          });
          if (currentResponse.status === 404) return null;
          if (!currentResponse.ok) {
            await currentResponse.text().catch(() => '');
            throw new Error(`Google Drive file verification failed with status ${currentResponse.status}`);
          }
          return await currentResponse.json();
        };

        let currentFile;
        try {
          currentFile = await readCurrentFile();
        } catch (verificationError) {
          console.error('Could not verify Google Drive file before delete:', verificationError?.message || verificationError);
          return Response.json({ error: 'Could not verify the Google Drive file before deleting it. Nothing was deleted.' }, { status: 502 });
        }

        if (!currentFile) {
          return Response.json({ success: true, alreadyDeleted: true });
        }

        const expectedName = String(expectedFileName || '').trim();
        const expectedModified = String(expectedModifiedTime || '').trim();
        if (!expectedName && !expectedModified) {
          return Response.json({ error: 'Deleting a Drive file requires expectedFileName or expectedModifiedTime for safety.' }, { status: 400 });
        }
        if (expectedName && String(currentFile.name || '') !== expectedName) {
          return Response.json({ error: 'The Google Drive file was renamed after this list was loaded. Reload before deleting it.' }, { status: 409 });
        }
        if (expectedModified && String(currentFile.modifiedTime || '') !== expectedModified) {
          return Response.json({ error: 'The Google Drive file changed after this list was loaded. Reload before deleting it.' }, { status: 409 });
        }

        const deleteUrl = `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(safeFileId)}?supportsAllDrives=true`;
        let deleteResponse;
        try {
          deleteResponse = await fetch(deleteUrl, {
            method: 'DELETE',
            headers: { 'Authorization': `Bearer ${accessToken}` }
          });
        } catch (deleteError) {
          // A network failure can happen after Google has already committed the
          // deletion. Reread the exact id before deciding whether retry is safe.
          try {
            const afterError = await readCurrentFile();
            if (!afterError) return Response.json({ success: true, recovered: true });
          } catch (verificationError) {
            console.error('Google Drive delete outcome is ambiguous:', verificationError?.message || verificationError);
            return Response.json({ error: 'The Google Drive delete outcome could not be verified. Reload Drive before trying again.' }, { status: 502 });
          }
          console.error('Google Drive delete failed before absence could be confirmed:', deleteError?.message || deleteError);
          return Response.json({ error: 'The Google Drive file was not confirmed deleted. Reload before trying again.' }, { status: 502 });
        }

        if (deleteResponse.status === 404) {
          return Response.json({ success: true, alreadyDeleted: true });
        }
        if (!deleteResponse.ok && deleteResponse.status !== 204) {
          await deleteResponse.text().catch(() => '');
          console.error('Google Drive delete failed:', deleteResponse.status);
          return Response.json({ error: 'Failed to delete Google Drive file' }, { status: deleteResponse.status });
        }

        return Response.json({ success: true });
      }

      default:
        return Response.json({ error: 'Invalid action' }, { status: 400 });
    }
  } catch (error) {
    const status = Number(error?.status || 500);
    const safeStatus = [400, 401, 409, 503].includes(status) ? status : 500;
    console.error('googleDriveOperations error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Google Drive operation could not be completed safely' : error.message,
    }, { status: safeStatus });
  }
});
